class Solution {
  public String maximumNumber(String num, int[] change) {
    char[] a = num.toCharArray();
    boolean started = false;
    for (int i = 0; i < a.length; i++) {
      int d = a[i] - '0', nd = change[d];
      if (nd > d) {
        a[i] = (char) ('0' + nd);
        started = true;
      } else if (started && nd < d) break;
    }
    return new String(a);
  }
}
